cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');

console.log('=== Sheet Names ===');
console.log(wb.SheetNames);

for (const name of wb.SheetNames) {
  const ws = wb.Sheets[name];
  const data = XLSX.utils.sheet_to_json(ws);
  const range = XLSX.utils.decode_range(ws['!ref']);
  console.log('\n=== Sheet:', name, '===');
  console.log('Rows:', data.length, '| Columns:', range.e.c - range.s.c + 1);

  const headers = Object.keys(data[0] || {});
  console.log('\nColumns:', headers.join(', '));

  console.log('\n--- First 10 Rows ---');
  console.table(data.slice(0, 10));

  console.log('\n--- Numeric Summary ---');
  for (const h of headers) {
    const vals = data.map(r => r[h]).filter(v => typeof v === 'number');
    if (vals.length > 0) {
      const sum = vals.reduce((a,b) => a+b, 0);
      const min = Math.min(...vals);
      const max = Math.max(...vals);
      const mean = sum / vals.length;
      console.log(h + ': count=' + vals.length + ', min=' + min.toFixed(2) + ', max=' + max.toFixed(2) + ', mean=' + mean.toFixed(2) + ', sum=' + sum.toFixed(2));
    }
  }

  // Unique value counts for non-numeric columns
  console.log('\n--- Categorical Columns ---');
  for (const h of headers) {
    const vals = data.map(r => r[h]).filter(v => v !== undefined && v !== null);
    const nonNumeric = vals.filter(v => typeof v !== 'number');
    if (nonNumeric.length > 0) {
      const uniq = [...new Set(vals)];
      console.log(h + ': ' + uniq.length + ' unique values' + (uniq.length <= 10 ? ' -> ' + uniq.join(', ') : ''));
    }
  }

  console.log('\n--- Null/Empty Counts ---');
  let anyNull = false;
  for (const h of headers) {
    const nulls = data.filter(r => r[h] === undefined || r[h] === null || r[h] === '').length;
    if (nulls > 0) { console.log(h + ': ' + nulls + ' missing'); anyNull = true; }
  }
  if (!anyNull) console.log('No missing values.');
}
"

cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);

// Status breakdown
const statusCounts = {};
const statusTotals = {};
data.forEach(r => {
  statusCounts[r.Status] = (statusCounts[r.Status] || 0) + 1;
  statusTotals[r.Status] = (statusTotals[r.Status] || 0) + r['Total Paid'];
});
console.log('=== Status Breakdown ===');
for (const s of Object.keys(statusCounts)) {
  console.log(s + ': ' + statusCounts[s] + ' orders, total \$' + statusTotals[s].toFixed(2));
}

// Customer breakdown
console.log('\n=== Customer Breakdown ===');
const custCounts = {};
const custTotals = {};
data.forEach(r => {
  custCounts[r.Customer] = (custCounts[r.Customer] || 0) + 1;
  custTotals[r.Customer] = (custTotals[r.Customer] || 0) + r['Total Paid'];
});
Object.keys(custCounts).sort((a,b) => custTotals[b]-custTotals[a]).forEach(c => {
  console.log(c + ': ' + custCounts[c] + ' orders, total \$' + custTotals[c].toFixed(2));
});

// Date breakdown
console.log('\n=== Date Breakdown ===');
const dateCounts = {};
data.forEach(r => { dateCounts[r.Date] = (dateCounts[r.Date] || 0) + 1; });
for (const d of Object.keys(dateCounts)) {
  console.log(d + ': ' + dateCounts[d] + ' orders');
}

// All rows
console.log('\n=== All 27 Rows ===');
console.table(data);
"
